package sources

import "time"

type TradingPair struct {
	Id     string `json:"id"`
	Name   string `json:"name"`
	Base   string `json:"base"`
	Quote  string `json:"quote"`
	Status string `json:"status"`
}

type ChartEntry struct {
	Timestamp time.Time `json:"timestamp"`

	Open   float64 `json:"open"`
	High   float64 `json:"high"`
	Low    float64 `json:"low"`
	Close  float64 `json:"close"`
	Volume float64 `json:"volume"`

	// Invalid is true when this entry is a placeholder for a missing timestamp
	// (generated by GenerateInvalidEntry). After ForwardFillInvalidEntries the
	// OHLCV values may have been filled from the previous valid entry so that
	// indicator calculations still work, but Invalid stays true so the chart
	// can render the slot as a gap.
	Invalid bool `json:"invalid"`
}

func GenerateInvalidEntry(timestamp time.Time) ChartEntry {
	return ChartEntry{
		Timestamp: timestamp,
		Open:      -999,
		High:      -999,
		Low:       -999,
		Close:     -999,
		Volume:    -999,
		Invalid:   true,
	}
}

func (c ChartEntry) IsValid() bool {
	return c.Open >= 0 && c.High >= 0 && c.Low >= 0 && c.Close >= 0 && c.Volume >= 0
}

// ForwardFillInvalidEntries replaces the OHLCV fields of every invalid entry
// with the values from the most-recent preceding valid entry, while keeping
// the Invalid flag set to true.  This lets indicators compute on meaningful
// numbers instead of the -999 sentinel, while the chart still renders the slot
// as a gap.  Entries that have no valid predecessor are left unchanged.
func ForwardFillInvalidEntries(entries []ChartEntry) []ChartEntry {
	result := make([]ChartEntry, len(entries))
	copy(result, entries)

	lastValidIdx := -1
	for i := range result {
		if !result[i].Invalid {
			lastValidIdx = i
		} else if lastValidIdx >= 0 {
			result[i].Open = result[lastValidIdx].Open
			result[i].High = result[lastValidIdx].High
			result[i].Low = result[lastValidIdx].Low
			result[i].Close = result[lastValidIdx].Close
			result[i].Volume = result[lastValidIdx].Volume
		}
		// No valid predecessor yet: leave the -999 sentinel values as-is.
	}
	return result
}

type TimeRange struct {
	Start time.Time
	End   time.Time
}

type SourcePairId struct {
	SourceName string
	PairId     string
}

func (s SourcePairId) String() string {
	return s.SourceName + ":" + s.PairId
}

type CandleColorConfig struct {
	BullishColor string
	BearishColor string
}
